              }
              if (isset($_SESSION['scriptcase']['bl_cta_corren_fornec']['glo_nm_perfil']) && $_SESSION['scriptcase']['bl_cta_corren_fornec']['glo_nm_perfil'] == $NM_con_orig)
              {
/*NM*/            $_SESSION['scriptcase']['bl_cta_corren_fornec']['glo_nm_perfil'] = $NM_con_dest;
              }
              if (isset($_SESSION['scriptcase']['bl_cta_corren_fornec']['glo_con_' . $NM_con_orig]))
              {
