        if($listaTitulos <> ''){
            $aTitulos = explode(',',$listaTitulos);
            if(is_array($aTitulos)){
                $tam = count($aTitulos);
                inserirLogDb('inicio laco do for $aTitulos - tamanho',$tam,__FUNCTION__);
                incrNivelCorrenteLogDb();
                for($i=0;$i<$tam;$i++){
